"""渲染用的静态模板：nginx 配置全文与 nginx 模型片段。

这里只有字符串常量，不含逻辑；改模板内容不影响任何函数签名。
"""

NGINX_CONF = """\
# ===== auto-generated by poolctl render — do not edit =====
# 入口层：监听公网 GATEWAY_PORT（模型面）+ 443（TLS），管理面统一限流。
# 部署位置：/etc/nginx/conf.d/orca.conf（http 上下文，故 zone/cache_path 可写在这里）。
#
# 拓扑：公网 → nginx(GATEWAY_PORT/443) → CPA(127.0.0.1:GATEWAY_INTERNAL_PORT)
# 管理面在 GATEWAY_PORT 上做限流，所以面板地址保持 http://<host>:<GATEWAY_PORT>/management.html 不变。

limit_req_zone $binary_remote_addr zone=orca_mgmt:10m rate=%(mgmt_rate)s;
limit_req_zone $binary_remote_addr zone=orca_quota:10m rate=%(quota_rate)s;
limit_req_status 429;

map $http_upgrade $connection_upgrade {
    default upgrade;
    ''      close;
}

upstream orca_cpa {
    server 127.0.0.1:%(internal_port)s;
    keepalive 64;
}

# 管理面公共片段：限流 + 真实来源透传（CPA 无 trusted-proxies，自己记不到）
server {
    listen %(port)s;
    listen [::]:%(port)s;
    server_name _;

    include /etc/nginx/snippets/orca-proxy.conf;

    # --- 管理面：面板 / 管理 API / HTTP 插件资源，一律限流 ---
    location = /management.html {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /assets/ {
        limit_req zone=orca_mgmt burst=100 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v0/management/ {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location = /v0/management {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v8/management/ {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    # --- 插件配额查询：人工触发，独立更严的桶 ---
    # 前缀 location 取最长匹配，所以这条会盖住上面的 /v0/management/，与书写顺序无关。
    location ^~ /v0/management/plugins/ {
        limit_req zone=orca_quota burst=5 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v0/resource/plugins/ {
        limit_req zone=orca_quota burst=5 nodelay;
        proxy_pass http://orca_cpa;
    }

    # --- 网关不支持 Files API：返回 404 而不是断连 ---
    # dsh 等客户端收到干净的 404 会立刻回退到内联图片；
    # 444 会被当成传输错误，可能重试并拖慢请求。
    location = /v1/files {
        return 404;
    }

    # --- 元数据：CPA 只校验 Bearer key，模型表用 render 产物对外展示 ---
    location = /_orca_models_auth {
        internal;
        proxy_pass_request_body off;
        proxy_set_header Content-Length "";
        proxy_set_header Authorization $http_authorization;
        proxy_method GET;
        proxy_pass http://orca_cpa/v1/models;
    }

    location = /v1/models {
        auth_request /_orca_models_auth;
        alias /etc/nginx/orca-models.json;
        default_type application/json;
        add_header Cache-Control "no-store" always;
    }

    # --- 模型面：不做任何速率/并发限制（限流会误伤重试与并行子 agent）---
    location / {
        proxy_pass http://orca_cpa;
    }
}

# TLS 入口：面板与 API 都可以走 https
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name _;

    ssl_certificate     /etc/nginx/ssl/orca.crt;
    ssl_certificate_key /etc/nginx/ssl/orca.key;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:orca_ssl:10m;
    ssl_session_timeout 1h;

    include /etc/nginx/snippets/orca-proxy.conf;

    location = /management.html {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /assets/ {
        limit_req zone=orca_mgmt burst=100 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v0/management/ {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location = /v0/management {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v8/management/ {
        limit_req zone=orca_mgmt burst=30 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v0/management/plugins/ {
        limit_req zone=orca_quota burst=5 nodelay;
        proxy_pass http://orca_cpa;
    }

    location ^~ /v0/resource/plugins/ {
        limit_req zone=orca_quota burst=5 nodelay;
        proxy_pass http://orca_cpa;
    }

    location = /v1/files {
        return 404;
    }

    location = /_orca_models_auth {
        internal;
        proxy_pass_request_body off;
        proxy_set_header Content-Length "";
        proxy_set_header Authorization $http_authorization;
        proxy_method GET;
        proxy_pass http://orca_cpa/v1/models;
    }

    location = /v1/models {
        auth_request /_orca_models_auth;
        alias /etc/nginx/orca-models.json;
        default_type application/json;
        add_header Cache-Control "no-store" always;
    }

    location / {
        proxy_pass http://orca_cpa;
    }
}
"""

# 公网监听端口 → CPA 回环端口的代理公共片段（keepalive / SSE / 真实来源）
NGINX_SNIPPET = """\
# ===== auto-generated by poolctl render — do not edit =====
proxy_http_version 1.1;
proxy_set_header Connection        $connection_upgrade;
proxy_set_header Upgrade           $http_upgrade;
proxy_set_header Host              $host;
proxy_set_header X-Real-IP         $remote_addr;
proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;

# 0 disables nginx's body-size check. opencode2api is patched to match.
client_max_body_size 0;

# SSE 长流：全链路不缓冲
proxy_buffering    off;
proxy_read_timeout 900s;
proxy_send_timeout 900s;
proxy_connect_timeout 10s;
"""
